export function InnerPage({slug}:{slug:string}){const{lang}=useLanguage();const c=configs[slug]||configs['learn'];return <><section className="topo bg-[#113a2f] py-24 text-white md:py-32"><div className="container"><p className="eyebrow">{c.kicker}</p><h1 className="mt-4 max-w-5xl text-[clamp(2.5rem,6vw,5rem)]">{t(lang,c.ka,c.en)}</h1><p className="mt-6 max-w-3xl text-lg text-white/70">{t(lang,c.dka,c.den)}</p></div></section>{slug.startsWith('history')?<History lang={lang} slug={slug}/>:slug.startsWith('learn')?<Learn lang={lang} slug={slug}/>:slug==='orienteering'?<Sport lang={lang}/>:slug==='federation'?<Federation lang={lang}/>:slug==='contact'?<Contact lang={lang}/>:<Library lang={lang} slug={slug}/>}</>}
